Security regression testing.ejemplo:
# Test de regresión para prevenir retorno de IDOR en endpoint de facturas
def test_prevent_idor_invoice_access(client, user_a_token, user_b_invoice_id):
    resp = client.get(
        f"/api/v1/invoices/{user_b_invoice_id}",
        headers={"Authorization": f"Bearer {user_a_token}"}
    )
    assert resp.status_code == 403
